sp_widget.client_script:
api.controller=function(){

var c=this;

c.search='';

c.results=[];

c.noResults=false;

c.searchNow=function(){

if(!c.search){

c.results=[];

c.noResults=false;

return;

}

c.server.get({

action:'search',

text:c.search

})

.then(function(r){

c.results=
r.data.results||[];

c.noResults=
c.results.length===0;


/* one result */

if(

c.results.length===1

){

window.location=

'/ev?id=employee_profile_details&sys_id=' + c.results[0]

.sys_id;

}

});

};

c.open=function(id){

window.location=

'/ev?id=employee_profile_details&sys_id=' + id;

};

};

sp_widget.css:
/* NAVBAR */

.ev-navbar{
border-top-left-radius: 20px;
border-top-right-radius: 20px;
margin:0%;

height:82px;

display:flex;

align-items:center;

justify-content:space-between;

padding:0 48px;

background:
linear-gradient(
90deg,
rgba(3,12,35,.96),
rgba(15,40,90,.95)
);

backdrop-filter:blur(22px);

box-shadow:
0 20px 60px rgba(0,0,0,.18);

position:relative;

z-index:100;

}


/* LOGO */

.logo a{

text-decoration:none;

color:white;

font-size:32px;

font-weight:900;

letter-spacing:-0.5px;

}


/* NAV */

.nav-links{

display:flex;

gap:34px;

align-items:center;

}

.nav-links a{

color:rgba(255,255,255,.82);

text-decoration:none;

font-size:15px;

font-weight:700;

position:relative;

transition:.25s;

}

.nav-links a:hover{

color:white;

}

.nav-links a:after{

content:'';

position:absolute;

bottom:-8px;

left:0;

width:0;

height:3px;

background:#2EE6B8;

border-radius:20px;

transition:.3s;

}

.nav-links a:hover:after{

width:100%;

}


/* SEARCH */

.search-area{

position:relative;

display:flex;

align-items:center;

min-width:260px;

}

.search-area input{

width:280px;

height:48px;

padding:0 64px 0 20px;

border:none;

outline:none;

border-radius:16px;

background:
rgba(255,255,255,.12);

color:white;

font-size:14px;

font-weight:700;

backdrop-filter:blur(20px);

transition:.25s;

}

.search-area input::placeholder{

color:
rgba(255,255,255,.55);

}

.search-area input:focus{

background:
rgba(255,255,255,.18);

box-shadow:
0 0 0 3px rgba(46,230,184,.22);

}

.search-btn{

position:absolute;

right:8px;

top:50%;

transform:translateY(-50%);

width:38px;

height:38px;

border:none;

border-radius:12px;

cursor:pointer;

background:
linear-gradient(
90deg,
#19D29D,
#39E0B0
);

font-size:16px;

color:white;

}

.search-btn:hover{

transform:
translateY(-50%)
scale(1.05);

}


/* SEARCH RESULTS */

.search-results{

position:absolute;

top:60px;

left:0;

width:100%;

background:#08162F;

border-radius:16px;

overflow:hidden;

box-shadow:
0 20px 40px rgba(0,0,0,.25);

}

.search-item{

padding:14px;

color:white;

cursor:pointer;

border-bottom:
1px solid rgba(255,255,255,.08);

}

.search-item:hover{

background:
rgba(59,130,246,.25);

}

.small{

margin-top:4px;

font-size:12px;

opacity:.65;

}

.no-results{

position:absolute;

top:60px;

left:0;

width:100%;

padding:16px;

background:#08162F;

color:#A8B4D6;

border-radius:16px;

}


/* MOBILE BUTTON */

/* MENU BUTTON */

.menu-toggle{

display:none;

width:42px;

height:42px;

position:relative;

background:none;

border:none;

cursor:pointer;

padding:0;

}


/* HAMBURGER LINES */

.menu-toggle span{

position:absolute;

left:8px;

width:26px;

height:3px;

background:white;

border-radius:10px;

transition:.3s ease;

}


/* TOP */

.menu-toggle span:nth-child(1){

top:12px;

}


/* MIDDLE */

.menu-toggle span:nth-child(2){

top:19px;

}


/* BOTTOM */

.menu-toggle span:nth-child(3){

top:26px;

}


/* OPEN → X */

.menu-toggle.active span:nth-child(1){

top:19px;

transform:
rotate(45deg);

}

.menu-toggle.active span:nth-child(2){

opacity:0;

}

.menu-toggle.active span:nth-child(3){

top:19px;

transform:
rotate(-45deg);

}


/* SHOW BUTTON ONLY MOBILE */

@media(max-width:950px){

.menu-toggle{

display:block;

}

}


/* LARGE TABLET */

@media(max-width:1200px){

.ev-navbar{

padding:0 32px;

}

.nav-links{

gap:22px;

}

.search-area input{

width:230px;

}

}


/* TABLET */

@media(max-width:950px){

.logo a{

font-size:28px;

}

.nav-links{

display:none;

}

.menu-toggle{

display:block;

}

.search-area{

min-width:220px;

}

.search-area input{

width:220px;

}

}


/* MOBILE */

@media(max-width:768px){

.ev-navbar{

flex-wrap:wrap;

height:auto;

padding:18px 20px;

gap:16px;

align-items:center;

}

.logo{

flex:1;

}

.search-area{

order:3;

width:100%;

}

.search-area input{

width:100%;

}

.nav-links.mobile-open{

display:flex;

flex-direction:column;

width:100%;

margin-top:10px;

padding:18px;

background:
rgba(5,18,45,.98);

border-radius:16px;

gap:18px;

animation:slideDown .25s ease;

}

.nav-links.mobile-open a{

font-size:14px;

}

}


@keyframes slideDown{

from{

opacity:0;

transform:translateY(-10px);

}

to{

opacity:1;

transform:translateY(0);

}

}

sp_widget.script:
(function(){

data.results=[];

if(
input &&
input.action==='search' &&
input.text
){

var search=
(input.text+'')
.toLowerCase();

var gr=
new GlideRecord(
'x_1902481_employ_0_employee'
);

gr.query();

while(gr.next()){

var employee=
gr.getDisplayValue();

if(

employee &&

employee
.toLowerCase()
.indexOf(search)>=0){

data.results.push({

sys_id:
gr.getUniqueValue(),

name:
employee,

designation:
gr.getDisplayValue(
'designation'
)

});

}

}

data.count=
data.results.length;

}

})();
